actions.css:
.section-2 {
  width: 100%;
  padding: clamp(0.75rem, 3vw, 1.25rem);
  box-sizing: border-box;
}



.section-3 {
  width: 100%;
  padding: clamp(0.75rem, 3vw, 1.25rem);
  box-sizing: border-box;
}



.rich-text-block {
  width: 100%;
  max-width: 58.75rem;
  margin: 0 auto;
  padding: 0 clamp(0.5rem, 2vw, 1.25rem);
  overflow-wrap: break-word;
  word-wrap: break-word;
}



.rich-text-block-4 {
  width: 100%;
  max-width: 58.75rem;
  margin: 0 auto;
  padding: 0 clamp(0.5rem, 2vw, 1.25rem);
  overflow-wrap: break-word;
  word-wrap: break-word;
}



.footer-dark {
  width: 100%;
  overflow: hidden;
  background-color: #46aa92;
  padding: 0 clamp(0.75rem, 3vw, 1.25rem);
  box-sizing: border-box;
}



.footer-wrapper {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  width: 100%;
  max-width: 56.25rem;
  margin: 0 auto;
}



.footer-content {
  display: grid;
  grid-template-columns: 1fr;
  gap: clamp(1.25rem, 4vw, 2rem);
  width: 100%;
  padding: clamp(1.5rem, 4vw, 2.1875rem) clamp(0.75rem, 3vw, 1.25rem) 0;
  box-sizing: border-box;
}



.footer-link {
  word-wrap: break-word;
  overflow-wrap: break-word;
}



.footer-social-block {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  justify-content: center;
}



@media screen and (min-width: 48rem) {
  .team-slide-wrapper {
    width: 47%;
    margin-right: 3%;
  }



  .footer-content {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }



  .button-11 {
    width: auto;
    max-width: 100%;
  }



  .button-12 {
    width: auto;
    max-width: 100%;
  }


}



@media screen and (min-width: 64rem) {
  .w-col-6 {
    flex: 1 1 calc(50% - 0.75rem);
    max-width: calc(50% - 0.75rem);
  }



  .team-slide-wrapper {
    width: 30%;
    margin-right: 5%;
  }



  .footer-content {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }


}



@media screen and (min-width: 90rem) {
  .div-block-3 {
    padding-left: 1.25rem;
    padding-right: 1.25rem;
  }


}



@media screen and (max-width: 47.9375rem) {
  .nav-menu-two {
    flex-direction: column;
    align-items: flex-start;
    width: 100%;
    padding-bottom: 0.75rem;
  }



  .nav-link-5 {
    display: block;
    padding: 0.5rem 0;
    width: 100%;
  }



  .nav-link-5-1 {
    display: block;
    padding: 0.5rem 0;
    width: 100%;
  }



  .menu-button-4 {
    display: block;
  }



  .button-11 {
    width: 100%;
    display: block;
  }



  .button-12 {
    width: 100%;
    display: block;
  }



  .button-13 {
    width: 100%;
    display: block;
  }



  .footer-content {
    text-align: center;
  }



  .footer-block {
    align-items: center;
  }



  .team-slide-wrapper {
    width: 100%;
    margin-right: 0;
  }



  .w-row {
    display: block;
  }



  .w-col {
    width: 100%;
    max-width: 100%;
    float: none;
    display: block;
    padding-left: 0;
    padding-right: 0;
  }



  .w-col-6 {
    width: 100%;
    max-width: 100%;
    float: none;
    display: block;
    padding-left: 0;
    padding-right: 0;
  }


}



@media screen and (max-width: 20rem) {
  .heading-56 {
    font-size: 1.125rem;
  }



  .heading-57 {
    font-size: 1rem;
  }



  .sunlu-hero-coupon-card {
    padding: 0.75rem;
  }


}
